import { useState } from "react";
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
    DialogTrigger,
} from "./ui/dialog";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { ScrollArea } from "./ui/scroll-area";
import { BookOpen, Search } from "lucide-react";

export function DictionaryModal({ onWordLookup }) {
    const [searchTerm, setSearchTerm] = useState("");
    const [searchResult, setSearchResult] = useState(null);
    const [isSearching, setIsSearching] = useState(false);

    // Mock dictionary data
    const mockDictionary = {
        hello: {
            word: "hello",
            pronunciation: "/həˈloʊ/",
            partOfSpeech: "interjection",
            definition: "Used as a greeting or to begin a phone conversation.",
            example: "Hello, how are you today?"
        },
        artificial: {
            word: "artificial",
            pronunciation: "/ˌɑːrtɪˈfɪʃəl/",
            partOfSpeech: "adjective",
            definition: "Made or produced by human beings rather than occurring naturally.",
            example: "The flowers were artificial, not real."
        },
        intelligence: {
            word: "intelligence",
            pronunciation: "/ɪnˈtelɪdʒəns/",
            partOfSpeech: "noun",
            definition: "The ability to acquire and apply knowledge and skills.",
            example: "She showed great intelligence in solving the problem."
        },
        chatbot: {
            word: "chatbot",
            pronunciation: "/ˈtʃætbɒt/",
            partOfSpeech: "noun",
            definition: "A computer program designed to simulate conversation with human users.",
            example: "The company uses a chatbot to answer customer questions."
        }
    };

    const handleSearch = async () => {
        if (!searchTerm.trim()) return;

        setIsSearching(true);

        // Simulate API call delay
        setTimeout(() => {
            const result = mockDictionary[searchTerm.toLowerCase()];
            if (result) {
                setSearchResult(result);
            } else {
                setSearchResult({
                    word: searchTerm,
                    pronunciation: "Not found",
                    partOfSpeech: "",
                    definition: `Sorry, we couldn't find a definition for "${searchTerm}". Try checking the spelling or searching for a different word.`,
                });
            }
            setIsSearching(false);
            if (onWordLookup) {
                onWordLookup(searchTerm);
            }
        }, 800);
    };

    const handleKeyPress = (e) => {
        if (e.key === 'Enter') {
            handleSearch();
        }
    };

    return (
        <Dialog>
            <DialogTrigger asChild>
                <Button
                    variant="outline"
                    size="sm"
                    className="bg-gradient-to-r from-slate-600 to-gray-700 text-white border-none hover:from-slate-700 hover:to-gray-800"
                >
                    <BookOpen className="w-4 h-4 mr-2" />
                    Dictionary
                </Button>
            </DialogTrigger>
            <DialogContent className="max-w-2xl">
                <DialogHeader>
                    <DialogTitle className="flex items-center gap-2">
                        <BookOpen className="w-5 h-5" />
                        Dictionary Lookup
                    </DialogTitle>
                </DialogHeader>

                <div className="space-y-4">
                    <div className="flex gap-2">
                        <Input
                            placeholder="Enter a word to look up..."
                            value={searchTerm}
                            onChange={(e) => setSearchTerm(e.target.value)}
                            onKeyPress={handleKeyPress}
                            className="flex-1"
                        />
                        <Button
                            onClick={handleSearch}
                            disabled={isSearching || !searchTerm.trim()}
                            className="bg-gradient-to-r from-slate-600 to-gray-700 hover:from-slate-700 hover:to-gray-800"
                        >
                            <Search className="w-4 h-4" />
                        </Button>
                    </div>

                    <ScrollArea className="h-[400px] w-full">
                        {isSearching ? (
                            <div className="flex items-center justify-center h-32">
                                <div className="flex items-center gap-2">
                                    <div className="w-4 h-4 bg-blue-500 rounded-full animate-bounce"></div>
                                    <div className="w-4 h-4 bg-slate-600 rounded-full animate-bounce" style={{ animationDelay: '0.1s' }}></div>
                                    <div className="w-4 h-4 bg-gray-500 rounded-full animate-bounce" style={{ animationDelay: '0.2s' }}></div>
                                    <span className="ml-2 text-sm text-muted-foreground">Searching...</span>
                                </div>
                            </div>
                        ) : searchResult ? (
                            <div className="space-y-4 p-4 bg-gradient-to-br from-slate-50 to-gray-100 rounded-lg">
                                <div className="border-b pb-2">
                                    <h3 className="text-2xl font-semibold text-blue-700">{searchResult.word}</h3>
                                    {searchResult.pronunciation !== "Not found" && (
                                        <p className="text-sm text-gray-600 italic">{searchResult.pronunciation}</p>
                                    )}
                                    {searchResult.partOfSpeech && (
                                        <span className="inline-block bg-blue-100 text-blue-800 text-xs px-2 py-1 rounded-full mt-1">
                                            {searchResult.partOfSpeech}
                                        </span>
                                    )}
                                </div>

                                <div>
                                    <h4 className="font-medium text-gray-700 mb-1">Definition:</h4>
                                    <p className="text-gray-800">{searchResult.definition}</p>
                                </div>

                                {searchResult.example && (
                                    <div>
                                        <h4 className="font-medium text-gray-700 mb-1">Example:</h4>
                                        <p className="text-gray-600 italic">"{searchResult.example}"</p>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="flex items-center justify-center h-32 text-muted-foreground">
                                <div className="text-center">
                                    <BookOpen className="w-12 h-12 mx-auto mb-2 opacity-50" />
                                    <p>Enter a word to search for its definition</p>
                                    <p className="text-sm mt-1">Try words like: hello, artificial, intelligence, chatbot</p>
                                </div>
                            </div>
                        )}
                    </ScrollArea>
                </div>
            </DialogContent>
        </Dialog>
    );
}
